<?xml version="1.0" encoding="UTF-8" standalone="no"?>
<mappingRoot xmlns="http://www.ibm.com/2008/ccl/Mapping" xmlns:map="default" domainID="com.ibm.msl.mapping.xml" domainIDExtension="mb" mainMap="true" targetNamespace="default" version="8.0.5.0">
    <input path="jar:file://!com/ibm/etools/mft/map/xsds/predefined/BlobMessage.xsd"/>
    <output path="jar:file://!com/ibm/etools/mft/map/xsds/predefined/JsonDomainMsg.xsd" var="var1"/>
    <output derivedFrom="MB:JSON_schema_in_json_file" path="/JSONSchema.json" var="var"/>
    <namespaces>
        <namespace kind="supplement" prefix="out" uri="http://www.ibm.com/iib/msl/json"/>
    </namespaces>
    <generation engine="xquery"/>
    <mappingDeclaration name="BLOBtoJSON_Mapping">
        <input path="mb:msg(BLOB,assembly,BLOB,Properties)" var="ComIbmMessageAssembly_BLOB"/>
        <output namespace="http://www.ibm.com/iib/msl/json" path="$var1/mb:msg(JSON,assembly,JSON,Properties)" var="ComIbmMessageAssembly_JSON">
            <cast derivedFrom="MB:JSON_TYPE" path="$ComIbmMessageAssembly_JSON/JSON/Data/type('anyType')" qualifier="{http://www.ibm.com/iib/msl/json}JSONArray_JSONSchema_JsonType" ref="var"/>
        </output>
        <move>
            <input path="$ComIbmMessageAssembly_BLOB/Properties"/>
            <output path="$ComIbmMessageAssembly_JSON/Properties"/>
        </move>
        <expression>
            <input path="$ComIbmMessageAssembly_BLOB/BLOB/text()" var="value1"/>
            <output path="$ComIbmMessageAssembly_JSON/JSON/spath('Data',2)/Item/LastName"/>
            <code lang="xpath">substring-after((tokenize(codepoints-to-string(&#13;
   for $index  in (1 to string-length(string($value1)))[. mod 2 = 1],&#13;
       $hinibble in (substring(string($value1), $index, 1)),&#13;
       $lonibble in (substring(string($value1), $index + 1, 1))&#13;
   return&#13;
       (16 * string-length(substring-before('0123456789ABCDEF', upper-case($hinibble)))) +&#13;
       string-length(substring-before('0123456789ABCDEF', upper-case($lonibble)))), '", "FirstName'&#13;
       )[1]),'LastName":"')</code>
        </expression>
        <expression>
            <input path="$ComIbmMessageAssembly_BLOB/BLOB/text()" var="value2"/>
            <output path="$ComIbmMessageAssembly_JSON/JSON/spath('Data',2)/Item/FirstName"/>
            <code lang="xpath">substring-after((tokenize(codepoints-to-string(&#13;
   for $index  in (1 to string-length(string($value2)))[. mod 2 = 1],&#13;
       $hinibble in (substring(string($value2), $index, 1)),&#13;
       $lonibble in (substring(string($value2), $index + 1, 1))&#13;
   return&#13;
       (16 * string-length(substring-before('0123456789ABCDEF', upper-case($hinibble)))) +&#13;
       string-length(substring-before('0123456789ABCDEF', upper-case($lonibble)))), '", "Address'&#13;
       )[1]),'FirstName":"')</code>
        </expression>
        <expression>
            <input path="$ComIbmMessageAssembly_BLOB/BLOB/text()" var="value3"/>
            <output path="$ComIbmMessageAssembly_JSON/JSON/spath('Data',2)/Item/Address"/>
            <code lang="xpath">substring-after((tokenize(codepoints-to-string(&#13;
   for $index  in (1 to string-length(string($value3)))[. mod 2 = 1],&#13;
       $hinibble in (substring(string($value3), $index, 1)),&#13;
       $lonibble in (substring(string($value3), $index + 1, 1))&#13;
   return&#13;
       (16 * string-length(substring-before('0123456789ABCDEF', upper-case($hinibble)))) +&#13;
       string-length(substring-before('0123456789ABCDEF', upper-case($lonibble)))), '", "DateOfBirth'&#13;
       )[1]),'Address":"')</code>
        </expression>
        <expression>
            <input path="$ComIbmMessageAssembly_BLOB/BLOB/text()" var="value4"/>
            <output path="$ComIbmMessageAssembly_JSON/JSON/spath('Data',2)/Item/DateOfBirth"/>
            <code lang="xpath">substring-after((tokenize(codepoints-to-string(&#13;
   for $index  in (1 to string-length(string($value4)))[. mod 2 = 1],&#13;
       $hinibble in (substring(string($value4), $index, 1)),&#13;
       $lonibble in (substring(string($value4), $index + 1, 1))&#13;
   return&#13;
       (16 * string-length(substring-before('0123456789ABCDEF', upper-case($hinibble)))) +&#13;
       string-length(substring-before('0123456789ABCDEF', upper-case($lonibble)))), '"\},\{"LastName'&#13;
       )[1]),'DateOfBirth":"')</code>
        </expression>
    </mappingDeclaration>
</mappingRoot>
